const number=(key,label,value,unit,min=0)=>({key,label,value,type:'number',unit,min,step:'any'});
const defs=[
 {slug:'unit-price-calculator',title:'Unit Price Calculator',category:'everyday',description:'Compare package sizes on equal terms. See the price per unit for two options and how much you save by choosing the better value.',fields:[number('costA','Option A price',4.5,'currency'),number('sizeA','Option A quantity',500,'units',.00001),number('costB','Option B price',7,'currency'),number('sizeB','Option B quantity',850,'units',.00001)],calculate(v){const a=Number(v.costA)/Number(v.sizeA),b=Number(v.costB)/Number(v.sizeB);if(!Number.isFinite(a+b)||Number(v.sizeA)<=0||Number(v.sizeB)<=0||Number(v.costA)<0||Number(v.costB)<0)throw Error('Use nonnegative prices and quantities greater than zero.');return{value:Math.min(a,b)*100,unit:'currency per 100 units',label:a===b?'Both options cost the same':`Option ${a<b?'A':'B'} offers better value`,details:[{label:'Option A / 100 units',value:a*100},{label:'Option B / 100 units',value:b*100},{label:'Price difference',value:`${Math.max(a,b)?((Math.abs(a-b)/Math.max(a,b))*100).toFixed(2):0}%`}],chart:[{label:'A / 100',value:a*100},{label:'B / 100',value:b*100}]};},formula:'Unit price = package price ÷ package quantity',explanation:'A larger package is not always cheaper. Unit pricing removes package size from the comparison. Enter both quantities in the same unit, such as grams, litres or pieces, and both prices in the same currency. The result compares the cost of 100 units so even small differences are easy to read. Quality, waste and storage life still matter; this calculator compares prices only.',example:'A 500 g package costing 4.50 costs 0.90 per 100 g. An 850 g package costing 7.00 costs about 0.82 per 100 g, making option B about 8.50% cheaper per gram.',faqs:[{q:'Can I compare litres and millilitres?',a:'Convert both quantities to the same unit first. Enter 1 litre as 1,000 millilitres if the other quantity is in millilitres.'},{q:'Does the currency matter?',a:'Any currency works if both prices use the same one. Convert prices first if they use different currencies.'}]},
 {slug:'reading-time-calculator',title:'Reading Time Calculator',category:'everyday',description:'Estimate how long an article, essay or document will take to read. Adjust reading speed for your audience and compare a fast read with a careful one.',fields:[{key:'text',label:'Text to read',type:'textarea',value:'Paste your article here to estimate how much time a reader will need.'},number('speed','Reading speed',225,'words/min',1)],calculate(v){const count=(String(v.text).trim().match(/\S+/g)||[]).length,speed=Number(v.speed);if(!count||speed<=0||!Number.isFinite(speed))throw Error('Add some text and a reading speed greater than zero.');return{value:count/speed,unit:'minutes',label:'Estimated reading time',details:[{label:'Word count',value:count},{label:'Careful read (150 wpm)',value:`${(count/150).toFixed(2)} min`},{label:'Quick read (300 wpm)',value:`${(count/300).toFixed(2)} min`}],chart:[{label:'Careful',value:count/150},{label:'Your pace',value:count/speed},{label:'Quick',value:count/300}],note:'This is a whitespace-based word estimate. Technical material, images and unfamiliar language can take longer.'};},formula:'Reading time in minutes = number of words ÷ words per minute',explanation:'Reading time gives readers a useful planning estimate, especially for newsletters and longer articles. Words are counted as groups of characters separated by whitespace. Adjust the reading speed rather than treating a single average as universal. A reader scanning familiar material may move quickly; a reader checking equations or learning a new subject needs more time. This estimate excludes time spent interpreting charts or following links.',example:'A 900-word article at 225 words per minute takes about four minutes. At a careful pace of 150 words per minute, allow six minutes.',faqs:[{q:'Is this a prediction of my actual reading speed?',a:'No. It applies the speed you enter to a simple word count. Your actual pace varies with the subject and purpose.'},{q:'Is my text uploaded?',a:'No. Counting happens in your browser. Avoid adding the text to a share link if you do not want it in the URL.'}]},
 {slug:'break-even-calculator',title:'Break-Even Calculator',category:'finance',description:'Find how many products you need to sell to cover fixed costs. Explore the relationship between price, variable cost and the contribution each sale makes.',fields:[number('fixed','Fixed costs',10000,'currency'),number('price','Selling price / unit',50,'currency'),number('variable','Variable cost / unit',30,'currency')],calculate(v){const f=Number(v.fixed),p=Number(v.price),c=Number(v.variable);if(!Number.isFinite(f+p+c)||f<0||c<0||p<=c)throw Error('Use nonnegative costs and a selling price above variable cost.');const n=Math.ceil(f/(p-c));return{value:n,unit:'units',label:'Sales needed to break even',details:[{label:'Contribution / unit',value:p-c},{label:'Revenue at break-even',value:n*p},{label:'Total costs at break-even',value:f+n*c}],chart:[{label:'Fixed cost',value:f},{label:'Variable costs',value:n*c},{label:'Revenue',value:n*p}],note:'Assumes constant selling price and variable cost. All production is sold; taxes and financing costs must be included in your cost inputs if relevant.'};},formula:'Break-even units = fixed costs ÷ (selling price − variable cost per unit), rounded up',explanation:'Fixed costs stay the same within the period you are modelling, while variable costs increase with each sale. The difference between selling price and variable cost is the contribution margin. Each sale uses that contribution to cover fixed costs; after those costs are covered, additional contribution becomes operating profit. A zero or negative contribution cannot cover fixed costs, so the calculator requires a selling price greater than the variable cost.',example:'With fixed costs of 10,000, a selling price of 50 and a variable cost of 30, each unit contributes 20. You need to sell 500 units to cover fixed costs.',faqs:[{q:'Which period should I use?',a:'Use one consistent period, such as a month or year. Enter only the fixed costs attributable to that period.'},{q:'What if I sell multiple products?',a:'A single-product model cannot account for changing sales mix. Use a weighted average contribution based on your expected mix, or calculate each product separately.'}]}
];

export const calculators=defs.map(tool=>({...tool,calculate(values){for(const field of tool.fields){if(field.type==='number'&&(String(values[field.key]??'').trim()===''||!Number.isFinite(Number(values[field.key]))))throw Error(`${field.label} must be a finite number.`);}return tool.calculate(values);}}));
